-- Client-facing master data. UTF-8; PostgreSQL; standard_conforming_strings=on.

-- Import into a fresh client database/schema. Existing tables are not overwritten.

-- Records: 100456. Original public IDs/codes are preserved.

BEGIN;

CREATE TABLE "hotel_cities" (
    "CityId" BIGINT PRIMARY KEY,
    "CityName" VARCHAR(200) NOT NULL,
    "DistrictName" VARCHAR(200),
    "StateName" VARCHAR(200),
    "CountryCode" VARCHAR(2) NOT NULL,
    "FullName" VARCHAR(750) NOT NULL,
    "Type" VARCHAR(30) NOT NULL,
    "HotelCount" INTEGER NOT NULL CHECK ("HotelCount" > 0)
);










































































































































































































COMMIT;
